# The bundle's host shim (generated by world/gen_hier.py bundle): the world's director_host (world/ above the package,
# metis.host.world_host) once a run names its game: $METIS_ALF_RUN/domains/hier/<this package>/game.json (gen_hier.install_run:
# the demo runs the bundle in place, the run's state under .metis/demo), or a game.json beside it (an install's); else
# metispy's PassHost: no world, the program alone (the console's REPL, metisc's).
import os

HERE = os.path.dirname(os.path.abspath(__file__))


def make(case=None):
    import metis.host as h                 # PassHost: metispy 0.2.1
    run = os.environ.get("METIS_ALF_RUN")
    pkg = os.path.join(run, "domains", "hier", os.path.basename(HERE)) if run else HERE
    if not os.path.exists(os.path.join(pkg, "game.json")):
        return h.PassHost()
    return h.world_host(HERE, "director_host", env="METIS_ALF_WORLD").DirectorHost(pkg, case)
